# A pull-request workflow on ordinary issues: an issue of the "Pull request"
# tracker names a branch (and a target branch, default main); this shows the
# branch's commits and diff on the issue, and closes it as merged once the
# branch has been merged into the target in git. See README.
Redmine::Plugin.register :git_pull_requests do
  name 'Pull requests'
  author "Colin 't Hart (code generated by Claude)"
  description 'Issues of a "Pull request" tracker show their branch\'s commits and diff, ' \
              'and are closed when the branch is merged.'
  version '0.1.0'
  url 'https://github.com/cthart/git_pull_requests'
  requires_redmine version_or_higher: '7.0.0'
end

# init.rb runs again at each code reload in development: prepend only once
unless Repository::Git <= GitPullRequests::RepositoryGitPatch
  Repository::Git.prepend GitPullRequests::RepositoryGitPatch
end
# Loading the class registers the view hook (Redmine::Hook::Listener.inherited)
GitPullRequests::Hooks.instance
